import {Window} from '/tmp/language-ui-check/node_modules/happy-dom/lib/index.js';
import {act} from 'react';
import {createRoot} from 'react-dom/client';
import {afterEach, expect, test, vi} from 'vitest';
import {configure} from '@gravity-ui/uikit';
import {getInitialLanguage, LanguageProvider, useLanguage, LANGUAGE_STORAGE_KEY} from './i18n';

vi.mock('@gravity-ui/uikit', () => ({configure: vi.fn()}));
const window = new Window({url: 'http://localhost:5173'});
vi.stubGlobal('window', window);
vi.stubGlobal('document', window.document);
vi.stubGlobal('navigator', {language: 'en-US'});
vi.stubGlobal('localStorage', window.localStorage);
vi.stubGlobal('IS_REACT_ACT_ENVIRONMENT', true);
afterEach(() => { localStorage.clear(); vi.restoreAllMocks(); });

function Probe() {
  const {language, setLanguage, t, saved} = useLanguage();
  return <button onClick={() => setLanguage(language === 'en' ? 'ru' : 'en')} data-saved={saved}>{t.settings}</button>;
}

test('switches translations, document metadata and UI kit, and restores preference after remount', async () => {
  const host = document.createElement('div');
  document.body.append(host);
  let root = createRoot(host);
  await act(async () => root.render(<LanguageProvider><Probe /></LanguageProvider>));
  expect(host.textContent).toBe('Settings');
  await act(async () => host.querySelector('button')"'!.click());
  expect(host.textContent).toBe('"'Настройки');
  expect(document.documentElement.lang).toBe('ru');
  expect(document.title).toBe('Настройки языка · Рабочее пространство');
  expect(configure).toHaveBeenLastCalledWith({lang: 'ru'});
  expect(localStorage.getItem(LANGUAGE_STORAGE_KEY)).toBe('ru');
  await act(async () => root.unmount());
  root = createRoot(host);
  await act(async () => root.render(<LanguageProvider><Probe /></LanguageProvider>));
  expect(host.textContent).toBe('Настройки');
  await act(async () => host.querySelector('button')"'!.click());
  expect(host.textContent).toBe('"'Settings');
  expect(localStorage.getItem(LANGUAGE_STORAGE_KEY)).toBe('en');
  await act(async () => root.unmount());
});

test('uses browser language, validates stored values and prioritizes saved preference', () => {
  vi.stubGlobal('navigator', {language: 'ru-RU'});
  expect(getInitialLanguage()).toBe('ru');
  localStorage.setItem(LANGUAGE_STORAGE_KEY, 'invalid');
  expect(getInitialLanguage()).toBe('ru');
  localStorage.setItem(LANGUAGE_STORAGE_KEY, 'en');
  expect(getInitialLanguage()).toBe('en');
  localStorage.clear();
  vi.stubGlobal('navigator', {language: 'fr-FR'});
  expect(getInitialLanguage()).toBe('en');
});

test('keeps switching available when storage is blocked', async () => {
  vi.stubGlobal('navigator', {language: 'en-US'});
  vi.spyOn(localStorage, 'getItem').mockImplementation(() => {throw new Error('blocked');});
  vi.spyOn(localStorage, 'setItem').mockImplementation(() => {throw new Error('blocked');});
  const host = document.createElement('div');
  const root = createRoot(host);
  await act(async () => root.render(<LanguageProvider><Probe /></LanguageProvider>));
  await act(async () => host.querySelector('button')"'!.click());
  expect(host.textContent).toBe('"'Настройки');
  expect(host.querySelector('button')"'!.getAttribute('"'data-saved')).toBe('false');
  await act(async () => root.unmount());
});
